CREATE TABLE IF NOT EXISTS users(id BIGSERIAL PRIMARY KEY,name VARCHAR(120) NOT NULL,email VARCHAR(190) UNIQUE NOT NULL,password_hash TEXT NOT NULL,role VARCHAR(20) NOT NULL DEFAULT 'admin',created_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE TABLE IF NOT EXISTS categories(id BIGSERIAL PRIMARY KEY,name VARCHAR(80) NOT NULL,slug VARCHAR(100) UNIQUE NOT NULL,description TEXT,created_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE TABLE IF NOT EXISTS sources(id BIGSERIAL PRIMARY KEY,name VARCHAR(120) NOT NULL,website_url TEXT,rss_url TEXT,category_id BIGINT REFERENCES categories(id) ON DELETE SET NULL,active BOOLEAN NOT NULL DEFAULT TRUE,created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE TABLE IF NOT EXISTS news_items(id BIGSERIAL PRIMARY KEY,source_id BIGINT NOT NULL REFERENCES sources(id) ON DELETE CASCADE,external_guid TEXT, title TEXT NOT NULL,description TEXT,url TEXT NOT NULL,image_url TEXT,published_at TIMESTAMPTZ,discovered_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),content_hash CHAR(64) NOT NULL UNIQUE,ignored BOOLEAN NOT NULL DEFAULT FALSE,UNIQUE(source_id,external_guid));
CREATE TABLE IF NOT EXISTS articles(id BIGSERIAL PRIMARY KEY,title TEXT NOT NULL,slug VARCHAR(220) UNIQUE NOT NULL,summary TEXT,content TEXT NOT NULL,seo_title TEXT,meta_description TEXT,featured_image TEXT,category_id BIGINT REFERENCES categories(id) ON DELETE SET NULL,status VARCHAR(20) NOT NULL DEFAULT 'draft',source_url TEXT,source_name TEXT,ai_generated BOOLEAN NOT NULL DEFAULT FALSE,published_at TIMESTAMPTZ,created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE TABLE IF NOT EXISTS article_sources(article_id BIGINT REFERENCES articles(id) ON DELETE CASCADE,news_item_id BIGINT REFERENCES news_items(id) ON DELETE CASCADE,PRIMARY KEY(article_id,news_item_id));
CREATE TABLE IF NOT EXISTS ai_generations(id BIGSERIAL PRIMARY KEY,article_id BIGINT REFERENCES articles(id) ON DELETE SET NULL,provider VARCHAR(40) NOT NULL,model VARCHAR(120),prompt TEXT,response TEXT,created_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE TABLE IF NOT EXISTS tags(id BIGSERIAL PRIMARY KEY,name VARCHAR(80) NOT NULL,slug VARCHAR(100) UNIQUE NOT NULL);
CREATE TABLE IF NOT EXISTS article_tags(article_id BIGINT REFERENCES articles(id) ON DELETE CASCADE,tag_id BIGINT REFERENCES tags(id) ON DELETE CASCADE,PRIMARY KEY(article_id,tag_id));
CREATE TABLE IF NOT EXISTS settings(id BIGSERIAL PRIMARY KEY,setting_key VARCHAR(120) UNIQUE NOT NULL,setting_value TEXT,updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE INDEX IF NOT EXISTS idx_articles_status ON articles(status); CREATE INDEX IF NOT EXISTS idx_articles_published_at ON articles(published_at); CREATE INDEX IF NOT EXISTS idx_news_source ON news_items(source_id); CREATE INDEX IF NOT EXISTS idx_news_published ON news_items(published_at);
INSERT INTO categories(name,slug,description) VALUES ('Technology','technology','Technology and innovation'),('Business','business','Markets, companies, and the economy'),('World','world','International news'),('Science','science','Research and discovery') ON CONFLICT(slug) DO NOTHING;
INSERT INTO sources(name,website_url,rss_url,category_id) SELECT 'BBC News','https://www.bbc.com/news','https://feeds.bbci.co.uk/news/rss.xml',id FROM categories WHERE slug='world' ON CONFLICT DO NOTHING;
INSERT INTO sources(name,website_url,rss_url,category_id) SELECT 'The Guardian','https://www.theguardian.com','https://www.theguardian.com/world/rss',id FROM categories WHERE slug='world' ON CONFLICT DO NOTHING;
INSERT INTO sources(name,website_url,rss_url,category_id) SELECT 'TechCrunch','https://techcrunch.com','https://techcrunch.com/feed/',id FROM categories WHERE slug='technology' ON CONFLICT DO NOTHING;
